  "lines-and-slope.rr.up": "Subir <b>{a}</b> es una elevación de <b>{r}</b>",
  "lines-and-slope.rr.down": "Bajar <b>{a}</b> es una elevación de <b>{r}</b>",
  "lines-and-slope.rr.downNeg": " — bajar cuenta como negativo.",
